/// <summary>
/// AVA/WEN/2025/07/04        AVA_013468_BlockExclusionRules
/// </summary>
/// <param name="sender">CredManCreditLimitCustGroupLine</param>
/// <param name="e">DataEventArgs</param>
[   SuppressBPWarning('BPParameterNotUsed', 'Parameter e required in signature'),
    DataEventHandler(tableStr(CredManCreditLimitCustGroupLine), DataEventType::Inserted)]
public static void CredManCreditLimitCustGroupLine_onInserted(Common sender, DataEventArgs e)
{
    CredManCreditLimitCustGroupLine     crlCustGroupLine = sender;
    CredManBlockExclusionRule           exclRule;

    select firstonly exclRule where exclRule.TableGroupAll == TableGroupAll::Table
        && exclRule.CustRelation == crlCustGroupLine.CustAccount
        && exclRule.DataAreaId == crlCustGroupLine.Company;
    if (exclRule)
    {
        delete_from exclRule where exclRule.TableGroupAll == TableGroupAll::Table 
                && exclRule.CustRelation == crlCustGroupLine.CustAccount
                && exclRule.DataAreaId == crlCustGroupLine.Company;
        warning(strFmt("@NDX:NXAExclRulesDeleted", crlCustGroupLine.CustAccount));
    }

}

/// <summary>
///
/// </summary>
/// <param name="sender"></param>
/// <param name="e"></param>
[DataEventHandler(tableStr(CredManCreditLimitCustGroupLine), DataEventType::ValidatingWrite)]
public static void CredManCreditLimitCustGroupLine_onValidatingWrite(Common sender, DataEventArgs e)
{
    ValidateEventArgs  validateEventArgs = e as ValidateEventArgs;
    CredManCreditLimitCustGroupLine crlGroupLine = sender;

    if (!crlGroupLine.CreditLimitCustGroup)
    {
        validateEventArgs.parmValidateResult(checkFailed("@NDX:NXACredManCustGroupLineError"));
    }
}
